begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
('11111111-1111-4111-8111-111111111111','owner@example.invalid',now()),
('22222222-2222-4222-8222-222222222222','agency@example.invalid',now());
create temporary table fixture(key text primary key,id uuid);
grant all on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into fixture values('brand',public.create_owner_workspace('Owner','Source brand','UTC','','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true));
insert into fixture values('source',public.register_brand_source((select id from fixture where key='brand'),'shopify','Primary store','TEST.example.invalid'));
select is((select state from public.brand_sources),'awaiting_authorization','New reference is never a connected account');
select is((select account_reference from public.brand_sources),'TEST.example.invalid','Reference case is preserved');
select is(public.register_brand_source((select id from fixture where key='brand'),'shopify','Primary store','TEST.example.invalid'),(select id from fixture where key='source'),'Retry does not duplicate account');
select is((select count(*)::int from public.brand_sources),1,'Only one source record created');
select throws_ok($$select public.register_brand_source((select id from fixture where key='brand'),'unknown','Test','test')$$,'23514',null,'Unsupported provider rejected');
select throws_ok($$select public.register_brand_source((select id from fixture where key='brand'),'ga4','','test')$$,'23514',null,'Empty account label rejected');
select throws_ok($$select public.set_brand_source_state((select id from fixture where key='brand'),(select id from fixture where key='source'),1,'connected')$$,'22023',null,'Client cannot mark unverified account connected');
select lives_ok($$select public.set_brand_source_state((select id from fixture where key='brand'),(select id from fixture where key='source'),1,'disabled')$$,'Operator can disable setup');
select throws_ok($$select public.set_brand_source_state((select id from fixture where key='brand'),(select id from fixture where key='source'),1,'awaiting_authorization')$$,'40001',null,'Stale resume rejected');
select lives_ok($$select public.set_brand_source_state((select id from fixture where key='brand'),(select id from fixture where key='source'),2,'awaiting_authorization')$$,'Current version can resume setup');
select is((select state from public.brand_sources),'awaiting_authorization','Resuming still requires authorization');
select throws_ok($$update public.brand_sources set state='disabled'$$,'42501',null,'Direct source changes denied');
insert into fixture values('invite',public.create_brand_invitation((select id from fixture where key='brand'),'agency@example.invalid','analyst',gen_random_uuid()));
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.brand_sources),0,'Unrelated user cannot read accounts');
select throws_ok($$select public.register_brand_source((select id from fixture where key='brand'),'ga4','Analytics','123')$$,'42501',null,'Unrelated user cannot register');
insert into fixture values('agency',public.create_agency('Agency',gen_random_uuid()));
select public.accept_brand_invitation((select id from fixture where key='invite'),(select id from fixture where key='agency'));
select is((select count(*)::int from public.brand_sources),1,'Analyst can inspect source state');
select throws_ok($$select public.set_brand_source_state((select id from fixture where key='brand'),(select id from fixture where key='source'),3,'disabled')$$,'42501',null,'Analyst cannot disable source');
reset role;
update public.brand_access_grants set access_level='operator' where brand_id=(select id from fixture where key='brand');
set local role authenticated;
select lives_ok($$select public.set_brand_source_state((select id from fixture where key='brand'),(select id from fixture where key='source'),3,'disabled')$$,'Agency operator can manage source setup');
insert into fixture values('otherbrand',public.create_owner_workspace('Agency owned','Other brand','UTC','','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true));
select throws_ok($$select public.set_brand_source_state((select id from fixture where key='otherbrand'),(select id from fixture where key='source'),4,'awaiting_authorization')$$,'42501',null,'Cross-brand source selector rejected');
reset role;
update public.brand_access_grants set active=false,revoked_at=now() where brand_id=(select id from fixture where key='brand');
set local role authenticated;
select is((select count(*)::int from public.brand_sources),0,'Revoked grant removes source reads');
select throws_ok($$select public.register_brand_source((select id from fixture where key='brand'),'ga4','Analytics','123')$$,'42501',null,'Revoked operator cannot register accounts');
reset role;
select is((select count(*)::int from audit.events where event_type like 'source.%'),4,'Registration and transitions are audited');
set local role anon;
select throws_ok($$select * from public.brand_sources$$,'42501',null,'Anonymous source reads denied');
reset role;
select * from finish();
rollback;
